# Comprehensive test: valid request with all field types
python3 << 'EOF'
import json
import subprocess

request = {
    "pipeline": {"steps": [
        {"op": "select", "columns": ["name", "age", "city"]},
        {"op": "filter", "where": "age > 18"},
        {"op": "map", "as": "adult_status", "expr": "age > 65 && 'senior' || 'adult'"},
        {"op": "branch", "branches": [
            {"when": "age > 65", "id": "seniors", "steps": [
                {"op": "rename", "mapping": {"age": "senior_age"}}
            ]},
            {"when": "otherwise", "id": "others", "steps": [
                {"op": "limit", "n": 100}
            ]}
        ], "merge": {"strategy": "concat"}}
    ]},
    "dataset": [
        {"name": "Alice", "age": 25, "city": "NYC"},
        {"name": "Bob", "age": 70, "city": "LA"},
        {"name": "Charlie", "age": 30, "city": "NYC"}
    ]
}

proc = subprocess.run(
    ["python", "etl_pipeline.py", "--execute"],
    input=json.dumps(request),
    capture_output=True,
    text=True
)
result = json.loads(proc.stdout)
print(f"Status: {result['status']}")
if result['status'] == 'ok':
    print(f"Rows in: {result['metrics']['rows_in']}")
    print(f"Rows out: {result['metrics']['rows_out']}")
    print(f"Sample row: {result['data'][0] if result['data'] else 'no data'}")
else:
    print(f"Error: {result['message']}")
    print(f"Path: {result['path']}")
EOF
